def evaluate(current_reputation, observation, my_history, round_num):
    action = observation.get('action', 'defect')
    recent = observation.get('recent_window', [])
    coop_count = sum(1 for r in recent if r.get('action') == 'cooperate')
    recent_score = coop_count / max(len(recent), 1)
    val = 1.0 if action == 'cooperate' else -1.0
    new_rep = current_reputation * 0.8 + val * 0.2 + recent_score * 0.1
    return max(-1.0, min(1.0, new_rep))

